# [doc = " A handle to an immutable memory mapped buffer."] # [doc = ""] # [doc = " A `Mmap` may be backed by a file, or it can be anonymous map, backed by volatile memory. Use"] # [doc = " [`MmapOptions`] or [`map()`] to create a file-backed memory map. To create an immutable"] # [doc = " anonymous memory map, first create a mutable anonymous memory map, and then make it immutable"] # [doc = " with [`MmapMut::make_read_only()`]."] # [doc = ""] # [doc = " A file backed `Mmap` is created by `&File` reference, and will remain valid even after the"] # [doc = " `File` is dropped. In other words, the `Mmap` handle is completely independent of the `File`"] # [doc = " used to create it. For consistency, on some platforms this is achieved by duplicating the"] # [doc = " underlying file handle. The memory will be unmapped when the `Mmap` handle is dropped."] # [doc = ""] # [doc = " Dereferencing and accessing the bytes of the buffer may result in page faults (e.g. swapping"] # [doc = " the mapped pages into physical memory) though the details of this are platform specific."] # [doc = ""] # [doc = " `Mmap` is [`Sync`] and [`Send`]."] # [doc = ""] # [doc = " See [`MmapMut`] for the mutable version."] # [doc = ""] # [doc = " ## Safety"] # [doc = ""] # [doc = " All file-backed memory map constructors are marked `unsafe` because of the potential for"] # [doc = " *Undefined Behavior* (UB) using the map if the underlying file is subsequently modified, in or"] # [doc = " out of process. Applications must consider the risk and take appropriate precautions when using"] # [doc = " file-backed maps. Solutions such as file permissions, locks or process-private (e.g. unlinked)"] # [doc = " files exist but are platform specific and limited."] # [doc = ""] # [doc = " ## Example"] # [doc = ""] # [doc = " ```"] # [doc = " use memmap2::MmapOptions;"] # [doc = " use std::io::Write;"] # [doc = " use std::fs::File;"] # [doc = ""] # [doc = " # fn main() -> std::io::Result<()> {"] # [doc = " let file = File::open(\"README.md\")?;"] # [doc = " let mmap = unsafe { MmapOptions::new().map(&file)? };"] # [doc = " assert_eq!(b\"# memmap2\", &mmap[0..9]);"] # [doc = " # Ok(())"] # [doc = " # }"] # [doc = " ```"] # [doc = ""] # [doc = " [`map()`]: Mmap::map()"] pub struct Mmap { inner : MmapInner , }
